settings.customCss:
.mfp-halloween-moonlit-rsvp{--mf-surface:#142922;--mf-ink:#f3f4ef;--mf-muted:#bbc8c0;--mf-line:#4a6155;--mf-control:#20382d;--mf-action:#ffc08b;--mf-action-ink:#25251f;--mf-focus:#d4c4f5;--mf-error:#ffb4b4;box-sizing:border-box;width:100%;max-width:760px;margin:0 auto;background:var(--mf-surface);color:var(--mf-ink);border:1px solid var(--mf-line);border-radius:8px;overflow:hidden;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;font-size:16px;line-height:1.5;letter-spacing:0}
.mfp-halloween-moonlit-rsvp *{box-sizing:border-box;min-width:0}
.mfp-halloween-moonlit-rsvp .form-header img{display:block;width:100%;height:168px;object-fit:cover}
.mfp-halloween-moonlit-rsvp .form-heading{padding:24px 32px 0}
.mfp-halloween-moonlit-rsvp .form-kicker{margin:0 0 6px;color:var(--mf-action);font-size:12px;font-weight:700;text-transform:uppercase}
.mfp-halloween-moonlit-rsvp h2{font-family:Georgia,"Times New Roman",serif;font-size:32px;font-weight:400;line-height:1.15;margin:0 0 10px;overflow-wrap:anywhere;letter-spacing:0}
.mfp-halloween-moonlit-rsvp .form-heading p:last-child{margin:0;color:var(--mf-muted);font-size:14px}
.mfp-halloween-moonlit-rsvp .form-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;padding:26px 32px 0}
.mfp-halloween-moonlit-rsvp .field-wide{grid-column:1 / -1}
.mfp-halloween-moonlit-rsvp .field-slot{overflow-wrap:anywhere}
.mfp-halloween-moonlit-rsvp .field-slot label{display:block;margin-bottom:8px;font-size:14px;font-weight:600;color:var(--mf-ink)}
.mfp-halloween-moonlit-rsvp .field-slot input{display:block;width:100%;min-height:46px;border:1px solid var(--mf-line);border-radius:4px;padding:10px 12px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-halloween-moonlit-rsvp .field-slot select{display:block;width:100%;min-height:46px;border:1px solid var(--mf-line);border-radius:4px;padding:10px 12px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-halloween-moonlit-rsvp .field-slot textarea{display:block;width:100%;min-height:88px;resize:vertical;border:1px solid var(--mf-line);border-radius:4px;padding:10px 12px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-halloween-moonlit-rsvp .field-slot input::placeholder{color:var(--mf-muted);opacity:1}
.mfp-halloween-moonlit-rsvp .field-slot textarea::placeholder{color:var(--mf-muted);opacity:1}
.mfp-halloween-moonlit-rsvp .field-slot small{display:block;margin-top:6px;color:var(--mf-muted);font-size:12px}
.mfp-halloween-moonlit-rsvp .field-slot [aria-invalid="true"]{border-color:var(--mf-error)}
.mfp-halloween-moonlit-rsvp .field-slot [role="alert"]{color:var(--mf-error);font-size:13px;margin-top:6px}
.mfp-halloween-moonlit-rsvp .field-slot input:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-halloween-moonlit-rsvp .field-slot select:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-halloween-moonlit-rsvp .field-slot textarea:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-halloween-moonlit-rsvp .form-actions{padding:24px 32px 0}
.mfp-halloween-moonlit-rsvp .form-actions button{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:48px;border:0;border-radius:4px;padding:12px 18px;background:var(--mf-action);color:var(--mf-action-ink);font:inherit;font-weight:700;cursor:pointer}
.mfp-halloween-moonlit-rsvp .form-actions button:hover{filter:brightness(1.06)}
.mfp-halloween-moonlit-rsvp .form-actions button:focus-visible{outline:3px solid var(--mf-focus);outline-offset:3px}
.mfp-halloween-moonlit-rsvp .form-actions button:disabled{opacity:0.65;cursor:wait}
.mfp-halloween-moonlit-rsvp .form-footer{padding:14px 32px 26px;color:var(--mf-muted);font-size:12px;text-align:center}
.mfp-halloween-moonlit-rsvp .field-slot [role="status"]{color:var(--mf-ink);overflow-wrap:anywhere}
@media(max-width:600px){.mfp-halloween-moonlit-rsvp .form-header img{height:124px}.mfp-halloween-moonlit-rsvp .form-heading{padding:20px 20px 0}.mfp-halloween-moonlit-rsvp h2{font-size:28px}.mfp-halloween-moonlit-rsvp .form-fields{grid-template-columns:1fr;padding:22px 20px 0;gap:18px}.mfp-halloween-moonlit-rsvp .form-actions{padding:22px 20px 0}.mfp-halloween-moonlit-rsvp .form-footer{padding:14px 20px 22px}}
